    p = np.zeros(3)
    r = np.eye(3)
    for fp, fr, j in _FIXED:
        p = p + r @ fp
        r = r @ fr
        if j is not None:
            r = r @ rotz(q[j])
    p = p + r @ _TOOL_P
    r = r @ _TOOL_R
    return p, r


def base_pose(obs):
