def ik_base(p_des, r_des, q0, iters=60, w_rot=0.5, q_rest=None, tol=2e-3):
    """Damped least-squares IK in the base frame; returns (q, position_error_m)."""
    q = clamp_limits(q0)
    eps = 1e-5
    for _ in range(iters):
        p, r = fk_base(q)
        ep = p_des - p
        er = rot_err(r, r_des) if r_des is not None else np.zeros(3)
        err = np.concatenate([ep, w_rot * er]) if r_des is not None else ep
        if np.linalg.norm(ep) < tol and (r_des is None or np.linalg.norm(er) < 0.02):
            break
        n = len(err)
        jac = np.zeros((n, 7))
        for i in range(7):
            dq = q.copy()
            dq[i] += eps
            p2, r2 = fk_base(dq)
            col = (p2 - p) / eps
            if r_des is not None:
