        step = jac.T @ np.linalg.solve(jjt, err)
        if q_rest is not None:
            null = np.eye(7) - jac.T @ np.linalg.solve(jjt, jac)
            step = step + 0.1 * null @ (np.asarray(q_rest) - q)
        nrm = np.linalg.norm(step)
        if nrm > 0.3:
            step = step * (0.3 / nrm)
        q = clamp_limits(q + step)
    p, _ = fk_base(q)
    return q, float(np.linalg.norm(p_des - p))


