    if arm_d is not None:
        for i in range(7):
            a[3 + i] = float(np.clip(arm_d[i], -amax, amax))
    a[10] = float(min(max(grip, 0.0), 1.0))
    if arm_v is not None:
        for i in range(7):
            a[11 + i] = float(np.clip(arm_v[i], -12.0, 12.0))
